api.look('noir');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 1.2);
const r = 70 + api.pulse(t, 1.2) * 6;
api.glow(cx, cy, 150, {c:'a3'});
api.circle(cx, cy, r, {c:'a3', w:5, k, fill:'ink'});
api.shape('person', cx, cy, 70, {c:'fg', w:4, k});
for (let i = 0; i < 6; i++) {
  const s = api.stag(t, i, {gap:0.2, dur:0.8, from:0.6});
  const a = i * Math.PI / 3 + 0.4;
  const d = 190 - 80 * s;
  api.line(cx + Math.cos(a) * d, cy + Math.sin(a) * d, cx + Math.cos(a) * (d + 40), cy + Math.sin(a) * (d + 40), {c:'bad', w:4, a:s});
}
api.say('Anxiety starts small', 0.3, 3.6);

api.look('noir');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 5.5);
const e = api.ease(k);
const rad = api.lerp(150, 52, e);
const sh = api.shake(t, 1 + 5 * e);
const pts = api.pts.circle(28, cx, cy, rad);
const jag = pts.map((p, i) => [p[0] + (api.noise(i * 3.1, t * 6) - 0.5) * 40 * e, p[1] + (api.noise(i * 7.7, t * 6) - 0.5) * 40 * e]);
api.glow(cx, cy, 200, {c:'bad', a:0.3 + 0.5 * e});
api.blob(jag, {c:'bad', w:4, fill:'panel'});
api.shape('person', cx, cy, 60, {c:'fg', w:4});
for (let i = 0; i < 12; i++) {
  const s = api.stag(t, i, {gap:0.25, dur:1.2, from:0});
  const a = i * Math.PI / 6;
  const d = api.lerp(330, rad + 30, s);
  api.dot(cx + Math.cos(a) * d, cy + Math.sin(a) * d, 5, {c:'warn'});
}
api.text('What if?', cx - 120, 140 + 20 * api.noise(t, 1), {size:28, c:'warn', font:'hand', k:api.seg(t, 1, 2)});
api.text('Too much', cx + 80, 640, {size:28, c:'warn', font:'hand', k:api.seg(t, 2, 3)});
api.text('Can\'t breathe', cx - 60, 220, {size:24, c:'bad', k:api.seg(t, 3.5, 4.5)});
api.counter(Math.round(60 + 80 * e), cx, 700, {size:44, suf:' bpm', k:1});
api.say('Pressure, racing heart, tight chest', 0.4, 5.5);

api.look('noir');
const cx = api.w/2, cy = 380;
const s = api.seg(t, 0, 3.4);
api.cam(0, 0, api.lerp(1, 1.4, api.ease(s)), 0);
api.shake(t, 6 * (1 - s));
const rad = 48 - 6 * api.pulse(t, 5);
api.glow(cx, cy, 240, {c:'bad'});
api.circle(cx, cy, rad, {c:'bad', w:6, fill:'panel'});
api.circle(cx, cy, rad + 22, {c:'warn', w:2, dash:[6, 6]});
api.arrow(cx - 150, cy - 220, cx - 40, cy - 40, {c:'warn', w:4, k:api.seg(t, 0, 1)});
api.arrow(cx + 150, cy - 220, cx + 40, cy - 40, {c:'warn', w:4, k:api.seg(t, 0.3, 1.3)});
api.arrow(cx, cy + 260, cx, cy + 50, {c:'warn', w:4, k:api.seg(t, 0.6, 1.6)});
api.cam0();
api.kinetic('Too much', cx, 700, {mode:'pop', k:api.seg(t, 1.5, 2.5), size:40, hot:'bad', t});
api.say('Then it peaks', 0.2, 3.5);

api.look('noir');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 1);
const breath = (1 - Math.cos(t * Math.PI * 2 / 4)) / 2;
const calm = api.ease(api.seg(t, 0, 5));
const rad = api.lerp(52, 100, breath) + calm * 20;
const col = calm > 0.5 ? 'a2' : 'a3';
api.glow(cx, cy, 160 + 80 * breath, {c:col});
api.circle(cx, cy, rad, {c:col, w:4, fill:'panel'});
api.circle(cx, cy, rad + 36 * breath, {c:'a2', w:2, a:0.5});
api.shape('person', cx, cy, 60, {c:'fg', w:4});
api.text(breath > 0.5 ? 'Out' : 'In', cx, cy + 190, {size:34, c:'a2', align:'center', k});
api.swarm(40, t, {mode:'rise', cx, cy:cy + 100, rx:200, ry:200, c:'a2', k:calm});
api.say('One slow breath in', 0.3, 2.8);
api.say('And out', 3, 5.8);

api.look('noir');
const cx = api.w/2, cy = 380;
const e = api.ease(api.seg(t, 0, 4));
api.stars(60, t);
api.swarm(80, t, {mode:'drift', cx, cy, rx:100 + 150 * e, ry:100 + 220 * e, c:'a2', glow:true, k:e});
api.glow(cx, cy, 260, {c:'a2', a:0.4 + 0.3 * e});
const pts = api.pts.circle(28, cx, cy, 110);
const soft = pts.map((p, i) => [p[0] + (api.noise(i * 2.3, t * 0.6) - 0.5) * 14, p[1] + (api.noise(i * 5.1, t * 0.6) - 0.5) * 14]);
api.blob(soft, {c:'a2', w:4, fill:'panel'});
api.shape('heart', cx, cy, 56, {c:'accent', w:4, fill:'accent', a:1});
for (let i = 0; i < 8; i++) {
  const s = api.stag(t, i, {gap:0.3, dur:2, from:0.5});
  const a = i * Math.PI / 4;
  const d = 140 + 200 * s;
  api.dot(cx + Math.cos(a) * d, cy + Math.sin(a) * d, 5 * (1 - s), {c:'warn'});
}
api.counter(Math.round(140 - 70 * e), cx, 700, {size:44, suf:' bpm', k:1});
api.say('The grip lets go', 0.4, 4);
api.say('Calm returns', 4.2, 6.8);

api.look('noir');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 3);
api.lineChart([{v:[0.1, 0.25, 0.45, 0.7, 0.95, 1, 0.6, 0.3, 0.15, 0.1, 0.08], c:'a2'}], 40, 220, api.w - 80, 300, {k, area:true, dots:true});
api.text('Anxiety', 60, 200, {size:20, c:'warn', k:api.seg(t, 0.5, 1.2)});
api.text('Peak', cx - 20, 190, {size:20, c:'bad', k:api.seg(t, 1.5, 2.2)});
api.text('Release', api.w - 130, 200, {size:20, c:'a2', k:api.seg(t, 2.5, 3.2)});
api.kinetic('It passes', cx, 620, {mode:'rise', k:api.seg(t, 3, 4.5), size:40, t});
api.say('It always passes', 0.3, 4.5);
